sys_script.script:
(function executeRule(current, previous /*null*/ ) {

    var newOutbound = false;
    var rpaMsg = '';
    if (current.payload) {
        var payloadObj = JSON.parse(current.payload);
        rpaMsg = payloadObj.rpa_message || '';
        if (rpaMsg.indexOf('Linked in GHSS') > -1) {
            newOutbound = true;
        }
    }
    // Get the related outbound record
    if (newOutbound) {
        var outboundGR = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
        outboundGR.addQuery('sn_task', current.message_id);
        outboundGR.query();
        if (outboundGR.next()) {
            // Build new payload for "D" maintenance
            var reqBody = JSON.parse(outboundGR.request_body);
            reqBody.HEADER.additionalattributes.link_maintenance = "D";
            var prevSysId = outboundGR.sn_task.sys_id.toString();
            var newMessageID = prevSysId.substring(0, prevSysId.length - 8) + gs.generateGUID().substring(0, 8);
            reqBody.HEADER.MessageID = newMessageID;
            reqBody.HEADER.additionalattributes.servicenowid = newMessageID;

            // Extract link reference from rpa_message
            var linkReference = '';
            if (current.payload) {
                var payloadObj = JSON.parse(current.payload);
                if (payloadObj.rpa_message) {
                    var match = payloadObj.rpa_message.match(/L-\d+/);
                    linkReference = match ? match[0] : '';
                }
            }
            // Set PAYLOAD to only contain link_reference
            reqBody.PAYLOAD = {
                link_reference: linkReference
            };

            var lastUpdateDateTime = reqBody.HEADER.additionalattributes.last_update_date_time;
            // Create new outbound record for RPA

            var amendUtils = new x_hsb11_mss_c_ghss.MSSGHSSAmendUtils();
            amendUtils.createOutBoundRecSingleSwitch(
                reqBody,
                outboundGR.sn_task,
                outboundGR.reference,
                outboundGR.lastUpdateDateTime
            );


        }
    }
})(current, previous);
